import type React from 'react';

export type TaskPriority = 'low' | 'medium' | 'high';

export type TaskStatus = 'todo' | 'in_progress' | 'done';

export interface KanbanTask {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  priority: TaskPriority;
  createdAt: string;
  dueDate: string;
}

export interface ColumnDef {
  id: TaskStatus;
  title: string;
  count: number;
  colorClass: string;
}

export interface TaskModalProps {
  isOpen: boolean;
  mode: 'create' | 'edit';
  initialTask: KanbanTask | null;
  onClose: () => void;
  onSave: (taskData: Omit<KanbanTask, 'id' | 'createdAt'>, taskId?: string) => void;
}

export interface TaskCardProps {
  task: KanbanTask;
  onDragStart: (e: React.DragEvent, id: string) => void;
  onDragEnd: () => void;
  onEdit: (task: KanbanTask) => void;
  onDelete: (id: string) => void;
  onQuickMove: (id: string, newStatus: TaskStatus) => void;
}

export interface KanbanColumnProps {
  column: ColumnDef;
  tasks: KanbanTask[];
  isDragOver: boolean;
  onDragOver: (e: React.DragEvent) => void;
  onDragLeave: () => void;
  onDrop: (e: React.DragEvent, status: TaskStatus) => void;
  onCardDragStart: (e: React.DragEvent, id: string) => void;
  onCardDragEnd: () => void;
  onEditTask: (task: KanbanTask) => void;
  onDeleteTask: (id: string) => void;
  onQuickMoveTask: (id: string, newStatus: TaskStatus) => void;
  onOpenCreate: (status: TaskStatus) => void;
}

import { useState } from 'react';
import { Pencil, Trash2, Calendar } from 'lucide-react';
import type { TaskCardProps, TaskPriority, TaskStatus } from '../types';

const PRIORITY_LABELS: Record<TaskPriority, string> = {
  high: '高優先度',
  medium: '中優先度',
  low: '低優先度',
};

const PRIORITY_CLASSES: Record<TaskPriority, string> = {
  high: 'priority-high',
  medium: 'priority-medium',
  low: 'priority-low',
};

const TaskCard = ({
  task,
  onDragStart,
  onDragEnd,
  onEdit,
  onDelete,
  onQuickMove,
}: TaskCardProps) => {
  const [isDragging, setIsDragging] = useState(false);

  const handleDragStart = (e: React.DragEvent) => {
    setIsDragging(true);
    onDragStart(e, task.id);
  };

  const handleDragEnd = () => {
    setIsDragging(false);
    onDragEnd();
  };

  const priorityClass = PRIORITY_CLASSES[task.priority] || 'priority-medium';
  const cardClassName = isDragging
    ? 'task-card task-card-dragging'
    : 'task-card';

  return (
    <div
      className={cardClassName}
      draggable
      onDragStart={handleDragStart}
      onDragEnd={handleDragEnd}
    >
      <div className="card-top-row">
        <span className={`card-priority-badge ${priorityClass}`}>
          {PRIORITY_LABELS[task.priority]}
        </span>
        <div className="card-action-group">
          <button
            type="button"
            className="btn-icon"
            onClick={() => onEdit(task)}
            title="タスクを編集"
            aria-label="タスクを編集"
          >
            <Pencil size={15} />
          </button>
          <button
            type="button"
            className="btn-icon"
            onClick={() => onDelete(task.id)}
            title="タスクを削除"
            aria-label="タスクを削除"
          >
            <Trash2 size={15} />
          </button>
        </div>
      </div>

      <h4 className="card-title">{task.title}</h4>

      {task.description && (
        <p className="card-desc">{task.description}</p>
      )}

      <div className="card-footer">
        <div className="card-date">
          <Calendar size={13} />
          <span>{task.dueDate ? `期日: ${task.dueDate}` : '期日なし'}</span>
        </div>

        <select
          className="mobile-move-select"
          value={task.status}
          onChange={(e) => onQuickMove(task.id, e.target.value as TaskStatus)}
          aria-label="ステータス変更"
        >
          <option value="todo">未着手へ移動</option>
          <option value="in_progress">作業中へ移動</option>
          <option value="done">完了へ移動</option>
        </select>
      </div>
    </div>
  );
};

export default TaskCard;

import { Plus } from 'lucide-react';
import type { KanbanColumnProps } from '../types';
import TaskCard from './TaskCard';

const KanbanColumn = ({
  column,
  tasks = [],
  isDragOver,
  onDragOver,
  onDragLeave,
  onDrop,
  onCardDragStart,
  onCardDragEnd,
  onEditTask,
  onDeleteTask,
  onQuickMoveTask,
  onOpenCreate,
}: KanbanColumnProps) => {
  const columnClassName = isDragOver
    ? 'kanban-column kanban-column-dragover'
    : 'kanban-column';

  return (
    <div
      className={columnClassName}
      onDragOver={onDragOver}
      onDragLeave={onDragLeave}
      onDrop={(e) => onDrop(e, column.id)}
    >
      <div className="column-header">
        <div className="column-title-wrap">
          <h3 className="column-title">{column.title}</h3>
          <span className="column-counter">{column.count}</span>
        </div>
        <button
          type="button"
          className="column-add-btn"
          onClick={() => onOpenCreate(column.id)}
          title={`${column.title}にタスクを追加`}
          aria-label={`${column.title}にタスクを追加`}
        >
          <Plus size={16} />
        </button>
      </div>

      <div className="task-list">
        {tasks.length === 0 ? (
          <div className="task-list-empty">
            タスクはありません
          </div>
        ) : (
          tasks.map((task) => (
            <TaskCard
              key={task.id}
              task={task}
              onDragStart={onCardDragStart}
              onDragEnd={onCardDragEnd}
              onEdit={onEditTask}
              onDelete={onDeleteTask}
              onQuickMove={onQuickMoveTask}
            />
          ))
        )}
      </div>
    </div>
  );
};

export default KanbanColumn;

import { useState, useEffect } from 'react';
import { X } from 'lucide-react';
import type { TaskModalProps, TaskPriority, TaskStatus } from '../types';

const TaskModal = ({
  isOpen,
  mode,
  initialTask,
  onClose,
  onSave,
}: TaskModalProps) => {
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [status, setStatus] = useState<TaskStatus>('todo');
  const [priority, setPriority] = useState<TaskPriority>('medium');
  const [dueDate, setDueDate] = useState('');
  const [error, setError] = useState('');

  useEffect(() => {
    if (initialTask) {
      setTitle(initialTask.title);
      setDescription(initialTask.description);
      setStatus(initialTask.status);
      setPriority(initialTask.priority);
      setDueDate(initialTask.dueDate);
    } else {
      setTitle('');
      setDescription('');
      setStatus('todo');
      setPriority('medium');
      setDueDate(new Date().toISOString().substring(0, 10));
    }
    setError('');
  }, [initialTask, isOpen]);

  if (!isOpen) {
    return null;
  }

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const trimmedTitle = title.trim();
    if (!trimmedTitle) {
      setError('タイトルを入力してください。');
      return;
    }

    onSave(
      {
        title: trimmedTitle,
        description: description.trim(),
        status,
        priority,
        dueDate,
      },
      initialTask ? initialTask.id : undefined
    );
  };

  return (
    <div className="modal-backdrop" onClick={onClose} role="presentation">
      <div
        className="modal-dialog"
        onClick={(e) => e.stopPropagation()}
        role="dialog"
        aria-modal="true"
        aria-labelledby="modal-title"
      >
        <div className="modal-header">
          <h3 id="modal-title" className="modal-title">
            {mode === 'create' ? '新規タスクの作成' : 'タスクの編集'}
          </h3>
          <button
            type="button"
            className="modal-close"
            onClick={onClose}
            aria-label="閉じる"
          >
            <X size={20} />
          </button>
        </div>

        <form onSubmit={handleSubmit}>
          <div className="modal-body">
            {error && (
              <p style={{ color: '#ef4444', fontSize: '0.875rem', marginBottom: '0.75rem' }}>
                {error}
              </p>
            )}

            <div className="form-group">
              <label htmlFor="task-title" className="form-label">
                タイトル <span style={{ color: '#ef4444' }}>*</span>
              </label>
              <input
                id="task-title"
                type="text"
                className="form-input"
                placeholder="タスクの要約を入力してください"
                value={title}
                onChange={(e) => setTitle(e.target.value)}
                autoFocus
              />
            </div>

            <div className="form-group">
              <label htmlFor="task-description" className="form-label">
                詳細説明
              </label>
              <textarea
                id="task-description"
                className="form-textarea"
                rows={3}
                placeholder="タスクの詳細やメモを入力してください"
                value={description}
                onChange={(e) => setDescription(e.target.value)}
              />
            </div>

            <div className="form-group">
              <label htmlFor="task-status" className="form-label">
                進行状況
              </label>
              <select
                id="task-status"
                className="form-select"
                value={status}
                onChange={(e) => setStatus(e.target.value as TaskStatus)}
              >
                <option value="todo">未着手</option>
                <option value="in_progress">作業中</option>
                <option value="done">完了</option>
              </select>
            </div>

            <div className="form-group">
              <label htmlFor="task-priority" className="form-label">
                優先度
              </label>
              <select
                id="task-priority"
                className="form-select"
                value={priority}
                onChange={(e) => setPriority(e.target.value as TaskPriority)}
              >
                <option value="low">低優先度</option>
                <option value="medium">中優先度</option>
                <option value="high">高優先度</option>
              </select>
            </div>

            <div className="form-group">
              <label htmlFor="task-due-date" className="form-label">
                期日
              </label>
              <input
                id="task-due-date"
                type="date"
                className="form-input"
                value={dueDate}
                onChange={(e) => setDueDate(e.target.value)}
              />
            </div>
          </div>

          <div className="modal-footer">
            <button
              type="button"
              className="btn btn-secondary"
              onClick={onClose}
            >
              キャンセル
            </button>
            <button
              type="submit"
              className="btn btn-primary"
            >
              {mode === 'create' ? '作成する' : '保存する'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default TaskModal;

import { useState, useMemo } from 'react';
import { Plus, Search } from 'lucide-react';
import type { ColumnDef, KanbanTask, TaskStatus } from './types';
import KanbanColumn from './components/KanbanColumn';
import TaskModal from './components/TaskModal';

const INITIAL_TASKS: KanbanTask[] = [
  {
    id: 'task-1',
    title: '新規ダッシュボードのデザイン作成',
    description: 'Figmaで全体のワイヤーフレームとカラーパレットの確定を行う',
    status: 'todo',
    priority: 'high',
    createdAt: '2025-02-15',
    dueDate: '2025-03-01',
  },
  {
    id: 'task-2',
    title: 'ユーザー登録APIの結合テスト',
    description: 'バリデーションエラーと重複メールアドレス時の挙動を確認する',
    status: 'todo',
    priority: 'medium',
    createdAt: '2025-02-16',
    dueDate: '2025-03-05',
  },
  {
    id: 'task-3',
    title: '利用規約・プライバシーポリシーの改訂',
    description: '法務担当者と内容のすり合わせ及び文面の最終確認',
    status: 'todo',
    priority: 'low',
    createdAt: '2025-02-17',
    dueDate: '2025-03-10',
  },
  {
    id: 'task-4',
    title: 'カンバンボードのドラッグ＆ドロップ実装',
    description: 'HTML5 Drag and Drop APIを用いて列間のステータス変更を可能にする',
    status: 'in_progress',
    priority: 'high',
    createdAt: '2025-02-18',
    dueDate: '2025-02-28',
  },
  {
    id: 'task-5',
    title: 'レスポンシブ表示の最適化',
    description: 'スマートフォン幅でのセレクト移動対応とUI調整',
    status: 'in_progress',
    priority: 'medium',
    createdAt: '2025-02-19',
    dueDate: '2025-03-02',
  },
  {
    id: 'task-6',
    title: 'CSSテーマとデザイントークンの適用',
    description: 'カラー変数やフォントサイズの統一、余白の最適化を実施',
    status: 'in_progress',
    priority: 'low',
    createdAt: '2025-02-20',
    dueDate: '2025-03-04',
  },
  {
    id: 'task-7',
    title: 'プロジェクトの初期設計ドキュメント作成',
    description: '型定義、コンポーネント構成、要件定義書の初版を完成',
    status: 'done',
    priority: 'high',
    createdAt: '2025-02-10',
    dueDate: '2025-02-15',
  },
  {
    id: 'task-8',
    title: '開発環境のセットアップ',
    description: 'Vite、TypeScript、ESLint、Prettierの導入と設定完了',
    status: 'done',
    priority: 'medium',
    createdAt: '2025-02-11',
    dueDate: '2025-02-14',
  },
];

const COLUMNS_BASE: { id: TaskStatus; title: string; colorClass: string }[] = [
  { id: 'todo', title: '未着手', colorClass: 'column-todo' },
  { id: 'in_progress', title: '作業中', colorClass: 'column-in-progress' },
  { id: 'done', title: '完了', colorClass: 'column-done' },
];

const App = () => {
  const [tasks, setTasks] = useState<KanbanTask[]>(INITIAL_TASKS);
  const [searchQuery, setSearchQuery] = useState('');
  const [draggedTaskId, setDraggedTaskId] = useState<string | null>(null);
  const [dragOverColumn, setDragOverColumn] = useState<TaskStatus | null>(null);

  // モーダル管理State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [modalMode, setModalMode] = useState<'create' | 'edit'>('create');
  const [editingTask, setEditingTask] = useState<KanbanTask | null>(null);

  // フィルタリング
  const filteredTasks = useMemo(() => {
    const query = searchQuery.trim().toLowerCase();
    if (!query) return tasks;
    return tasks.filter(
      (task) =>
        task.title.toLowerCase().includes(query) ||
        task.description.toLowerCase().includes(query)
    );
  }, [tasks, searchQuery]);

  // カラム定義の計算
  const columns: ColumnDef[] = useMemo(() => {
    return COLUMNS_BASE.map((col) => ({
      ...col,
      count: filteredTasks.filter((t) => t.status === col.id).length,
    }));
  }, [filteredTasks]);

  // 全体統計
  const stats = useMemo(() => {
    const total = tasks.length;
    const todo = tasks.filter((t) => t.status === 'todo').length;
    const inProgress = tasks.filter((t) => t.status === 'in_progress').length;
    const done = tasks.filter((t) => t.status === 'done').length;
    return { total, todo, inProgress, done };
  }, [tasks]);

  // ドラッグ操作ハンドラ
  const handleCardDragStart = (e: React.DragEvent, id: string) => {
    setDraggedTaskId(id);
    e.dataTransfer.setData('text/plain', id);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleCardDragEnd = () => {
    setDraggedTaskId(null);
    setDragOverColumn(null);
  };

  const handleColumnDragOver = (e: React.DragEvent, status: TaskStatus) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
    if (dragOverColumn !== status) {
      setDragOverColumn(status);
    }
  };

  const handleColumnDragLeave = () => {
    setDragOverColumn(null);
  };

  const handleColumnDrop = (e: React.DragEvent, targetStatus: TaskStatus) => {
    e.preventDefault();
    const taskId = e.dataTransfer.getData('text/plain') || draggedTaskId;
    if (taskId) {
      setTasks((prev) =>
        prev.map((task) =>
          task.id === taskId ? { ...task, status: targetStatus } : task
        )
      );
    }
    setDraggedTaskId(null);
    setDragOverColumn(null);
  };

  // スマホ用クイック移動
  const handleQuickMoveTask = (id: string, newStatus: TaskStatus) => {
    setTasks((prev) =>
      prev.map((task) =>
        task.id === id ? { ...task, status: newStatus } : task
      )
    );
  };

  // タスク削除
  const handleDeleteTask = (id: string) => {
    setTasks((prev) => prev.filter((task) => task.id !== id));
  };

  // タスク追加モーダルを開く
  const handleOpenCreateModal = (defaultStatus: TaskStatus = 'todo') => {
    setModalMode('create');
    setEditingTask({
      id: '',
      title: '',
      description: '',
      status: defaultStatus,
      priority: 'medium',
      createdAt: '',
      dueDate: new Date().toISOString().substring(0, 10),
    });
    setIsModalOpen(true);
  };

  // タスク編集モーダルを開く
  const handleOpenEditModal = (task: KanbanTask) => {
    setModalMode('edit');
    setEditingTask(task);
    setIsModalOpen(true);
  };

  // モーダル保存
  const handleSaveTask = (
    taskData: Omit<KanbanTask, 'id' | 'createdAt'>,
    taskId?: string
  ) => {
    if (modalMode === 'create' || !taskId) {
      const newTask: KanbanTask = {
        ...taskData,
        id: `task-${Date.now()}`,
        createdAt: new Date().toISOString().substring(0, 10),
      };
      setTasks((prev) => [newTask, ...prev]);
    } else {
      setTasks((prev) =>
        prev.map((task) =>
          task.id === taskId ? { ...task, ...taskData } : task
        )
      );
    }
    setIsModalOpen(false);
    setEditingTask(null);
  };

  return (
    <div className="app-container">
      <header className="header">
        <div className="header-title-group">
          <h1 className="header-title">カンバンボード</h1>
          <p className="header-subtitle">
            ドラッグ＆ドロップでタスクの進捗状況をリアルタイムに整理できます
          </p>
        </div>

        <div className="header-controls">
          <div className="search-bar">
            <Search size={18} style={{ color: '#94a3b8' }} />
            <input
              type="text"
              className="search-input"
              placeholder="タスクを検索..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>

          <button
            type="button"
            className="btn btn-primary"
            onClick={() => handleOpenCreateModal('todo')}
          >
            <Plus size={18} />
            <span>新規タスク</span>
          </button>
        </div>
      </header>

      <div className="stats-bar">
        <div className="stat-badge">全タスク: {stats.total}件</div>
        <div className="stat-badge">未着手: {stats.todo}件</div>
        <div className="stat-badge">作業中: {stats.inProgress}件</div>
        <div className="stat-badge">完了: {stats.done}件</div>
      </div>

      <main className="kanban-board">
        {columns.map((column) => {
          const columnTasks = filteredTasks.filter(
            (task) => task.status === column.id
          );
          return (
            <KanbanColumn
              key={column.id}
              column={column}
              tasks={columnTasks}
              isDragOver={dragOverColumn === column.id}
              onDragOver={(e) => handleColumnDragOver(e, column.id)}
              onDragLeave={handleColumnDragLeave}
              onDrop={handleColumnDrop}
              onCardDragStart={handleCardDragStart}
              onCardDragEnd={handleCardDragEnd}
              onEditTask={handleOpenEditModal}
              onDeleteTask={handleDeleteTask}
              onQuickMoveTask={handleQuickMoveTask}
              onOpenCreate={handleOpenCreateModal}
            />
          );
        })}
      </main>

      <TaskModal
        isOpen={isModalOpen}
        mode={modalMode}
        initialTask={editingTask}
        onClose={() => {
          setIsModalOpen(false);
          setEditingTask(null);
        }}
        onSave={handleSaveTask}
      />
    </div>
  );
};

export default App;
